// Pipeline lazy con generadores
// Los generadores procesan elemento por elemento — no crean arrays intermedios

function* map(iterable, fn) {
  for (const x of iterable) yield fn(x);
}

function* filter(iterable, pred) {
  for (const x of iterable) if (pred(x)) yield x;
}

function* take(iterable, n) {
  let count = 0;
  for (const x of iterable) {
    if (count++ >= n) break;
    yield x;
  }
}

// Generador infinito de números naturales
function* naturales() {
  let n = 1;
  while (true) yield n++;
}

// Pipeline: tomar los primeros 5 números pares al cuadrado
const resultado = take(
  map(
    filter(naturales(), n => n % 2 === 0),
    n => n ** 2
  ),
  5
);

console.log([...resultado]); // [4, 16, 36, 64, 100]

// Generador de combinaciones (útil para pruebas o puzzles)
function* combinaciones(arr, r) {
  if (r === 1) {
    for (const x of arr) yield [x];
    return;
  }
  for (let i = 0; i <= arr.length - r; i++) {
    for (const combo of combinaciones(arr.slice(i + 1), r - 1)) {
      yield [arr[i], ...combo];
    }
  }
}

const letras = ['a', 'b', 'c', 'd'];
const combos = [...combinaciones(letras, 2)];
console.log(combos);
// [['a','b'],['a','c'],['a','d'],['b','c'],['b','d'],['c','d']]
console.log('Total combinaciones C(4,2):', combos.length); // 6

