function* mapGen(iterable, fn) {
  for (const x of iterable) yield fn(x);
}

function* filterGen(iterable, pred) {
  for (const x of iterable) if (pred(x)) yield x;
}

function* takeGen(iterable, n) {
  let count = 0;
  for (const x of iterable) {
    if (count >= n) break;
    yield x;
    count++;
  }
}

const empleados = [
  { nombre: 'Ana',   dept: 'tech', salario: 5000 },
  { nombre: 'Bob',   dept: 'hr',   salario: 3500 },
  { nombre: 'Carl',  dept: 'tech', salario: 6000 },
  { nombre: 'Diana', dept: 'tech', salario: 7000 },
  { nombre: 'Eve',   dept: 'hr',   salario: 4000 },
];

// Pipeline: filtrar tech con salario > 5000, tomar 2, extraer nombres
const techSenior = filterGen(empleados, e => e.dept === 'tech' && e.salario > 5000);
const top2 = takeGen(techSenior, 2);
const nombres = [...mapGen(top2, e => e.nombre)];

console.log('Top 2 tech senior:', nombres);
